12	/**
13	 * Runs first on {@code POST /api/owners}. When the request carries an {@code Idempotency-Key} that
14	 * was already used to create an owner, it throws {@link IdempotentReplayException} to short-circuit
15	 * the pipeline and replay that owner with 200 — before the duplicate-identity check would otherwise
16	 * reject the repeat with 409. Otherwise it republishes the key (which may be absent) so
17	 * {@link RecordIdempotency} can remember it once the new owner is saved. Does not read the request
18	 * body, leaving that to {@link ValidateOwnerFields}.
19	 */
20	public class CheckIdempotency {
21	
22	    public void service(
23	            @RequestHeader(name = "Idempotency-Key", required = false) String key,
24	            IdempotencyStore store, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
25	            Out<String> idempotencyKey) throws IdempotentReplayException {
26	        idempotencyKey.set(key);
27	        if (key == null || key.isBlank()) {
28	            return; // no key: proceed with a normal create
29	        }
30	        Integer existingId = store.find(key);
31	        if (existingId == null) {
32	            return; // first time this key is seen: proceed and record after save
33	        }
34	        Owner existing = ownerRepository.findById(existingId);
35	        if (existing != null) {
36	            // Map while the persistence context is still open, then replay with 200.
37	            throw new IdempotentReplayException(ownerMapper.toOwnerDto(existing));
38	        }
