96	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
97	            throws MissingFieldsException {
98	        List<String> errors = new ArrayList<>();
99	        if (isBlank(request.getFirstName())) {
100	            errors.add("firstName");
101	        }
102	        if (isBlank(request.getLastName())) {
103	            errors.add("lastName");
104	        }
105	        applyAddress(request, errors);
106	        if (isBlank(request.getCity())) {
107	            errors.add("city");
108	        }
109	        String telephone = TelephoneE164.normalize(request.getTelephone());
110	        if (telephone == null) {
111	            errors.add("telephone");
112	        }
113	        else {
114	            request.setTelephone(telephone);
115	        }
116	        String email = request.getEmail();
117	        if (email != null && !email.isBlank()) {
118	            String normalized = email.trim().toLowerCase();
119	            if (!EMAIL.matcher(normalized).matches()) {
120	                errors.add("email");
121	            }
122	            else if (DISPOSABLE_DOMAINS.contains(normalized.substring(normalized.indexOf('@') + 1))) {
123	                errors.add("email");
124	            }
125	            else {
126	                request.setEmail(normalized);
127	            }
128	        }
129	        // Postcode is optional; validated only when present. A malformed (non-4-digit) postcode
130	        // is a 400, and a well-formed postcode outside its city's region range is a 400 too.
131	        // A city with no known region accepts any 4-digit postcode.
132	        String postcode = request.getPostcode();
133	        if (postcode != null && !postcode.isBlank()) {
134	            String trimmed = postcode.trim();
135	            if (!POSTCODE.matcher(trimmed).matches() || !inRegionRange(request.getCity(), trimmed)) {
136	                errors.add("postcode");
137	            }
138	            else {
