143	        // server's current date is a 400 — an owner cannot be registered in the future.
144	        LocalDate registrationDate = request.getRegistrationDate();
145	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
146	            errors.add("registrationDate");
147	        }
