163	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
164	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
165	        String flat = AddressNormalizer.normalize(request.getAddress());
166	        if (!line1.isEmpty()) {
167	            request.setAddressLine1(line1);
168	            String composed = line1;
169	            if (!line2.isEmpty()) {
170	                request.setAddressLine2(line2);
171	                composed = line1 + " " + line2;
172	            }
173	            else {
174	                request.setAddressLine2(null);
175	            }
176	            request.setAddress(composed);
177	        }
178	        else if (!flat.isEmpty()) {
179	            request.setAddress(flat);
180	        }
181	        else {
