183	        }
184	    }
185	
186	    private static boolean isBlank(String value) {
187	        return value == null || value.isBlank();
188	    }
189	
190	    /** True when the 4-digit {@code postcode} is acceptable for the city's region: either the
191	     *  city has no known region (accepts any 4-digit postcode) or the postcode falls within the
192	     *  region's inclusive range. */
