496	        String code = base;
497	        for (int n = 2; taken.contains(code); n++) {
498	            code = base + "-" + n;
499	        }
500	        owner.setCustomerCode(code);
501	    }
502	
503	    /** The first eight upper-case hex characters of the SHA-256 digest of {@code s}. */
504	    private static String sha256Hex8(String s) {
505	        byte[] digest;
