507	            digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
508	        }
509	        catch (NoSuchAlgorithmException ex) {
510	            throw new IllegalStateException("SHA-256 not available", ex);
511	        }
512	        StringBuilder sb = new StringBuilder(8);
513	        for (int i = 0; sb.length() < 8; i++) {
