592	/**
593	 * Assigns the owner's soft-match duplicate signal. A create request that clears the hard
594	 * duplicate check (see {@link EnsureUniqueIdentity}) may still resemble an existing owner: when
595	 * the new owner shares an existing owner's lastName (compared case-insensitively with collapsed
596	 * whitespace) and postcode while carrying a different telephone, it is still created but flagged
597	 * with {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to that existing
598	 * owner's id. Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null.
599	 *
600	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: it shares an
601	 * existing member's lastName and postcode by design, so it is a known household member rather than
602	 * a suspected duplicate. (A same lastName + postcode owner that did <em>not</em> declare the
603	 * household is already rejected as a household duplicate by {@link EnsureUniqueIdentity} and never
604	 * reaches this step.)
605	 *
606	 * <p>Only owners with a postcode participate: a match requires both postcodes to be present and
607	 * equal. When several existing owners match, the earliest (lowest id) is reported. Runs before
608	 * {@code save}, so the new owner is not compared against itself.
609	 */
610	public class AssignPossibleDuplicate {
611	
612	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
613	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
614	            owner.setPossibleDuplicate(false);
615	            owner.setPossibleDuplicateOf(null);
616	            return; // a declared household member is not a suspected duplicate
617	        }
618	        String lastName = normalize(owner.getLastName());
619	        String postcode = owner.getPostcode();
620	        String telephone = owner.getTelephone();
621	        Owner match = null;
622	        if (postcode != null && !postcode.isBlank()) {
623	            for (Owner existing : ownerRepository.findAll()) {
624	                if (existing.isDeleted()) {
625	                    continue; // a soft-deleted owner is not a soft-match candidate
626	                }
627	                if (lastName.equals(normalize(existing.getLastName()))
628	                        && postcode.equals(existing.getPostcode())
629	                        && !equalsTelephone(telephone, existing.getTelephone())) {
630	                    if (match == null || lessThan(existing.getId(), match.getId())) {
631	                        match = existing;
632	                    }
633	                }
634	            }
635	        }
636	        if (match != null) {
637	            owner.setPossibleDuplicate(true);
638	            owner.setPossibleDuplicateOf(match.getId());
639	        }
640	        else {
641	            owner.setPossibleDuplicate(false);
642	            owner.setPossibleDuplicateOf(null);
643	        }
644	    }
645	
646	    private static boolean equalsTelephone(String a, String b) {
647	        return a == null ? b == null : a.equals(b);
648	    }
649	
650	    private static boolean lessThan(Integer a, Integer b) {
651	        if (a == null) {
652	            return false;
653	        }
654	        if (b == null) {
655	            return true;
656	        }
657	        return a < b;
658	    }
659	
660	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
661	     *  single space, and lower-case. */
662	    private static String normalize(String value) {
663	        if (value == null) {
664	            return "";
665	        }
666	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
667	    }
668	}
